 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--seed-start',type=int,default=93001);p.add_argument('--seeds',type=int,default=30);p.add_argument('--contiki',type=Path,required=True);p.add_argument('--cooja',type=Path,required=True);p.add_argument('--java',type=Path,required=True);p.add_argument('--make-bin',type=Path);a=p.parse_args();r=Path(__file__).resolve().parents[1];out=a.output.resolve();out.mkdir(parents=True,exist_ok=True)
 if any(out.iterdir()):raise SystemExit('Refusing to overwrite experiment')
 sources=[Path(__file__).resolve(),r/'scripts/audit_cooja_feedback.py',r/'scripts/prepare_cooja_feedback.py',r/'scripts/check_cooja_feedback_ledger.py',r/'hardware/cooja_feedback/pilot.csc',r/'hardware/cooja_feedback/Makefile',r/'hardware/cooja_feedback/cooja-radio-observer.patch',r/'hardware/cooja_feedback/feedback.c',r/'hardware/cooja_feedback/local_feedback.h',r/'hardware/cooja_feedback/feedback_ledger.h',r/'hardware/cooja_feedback/project-conf.h',r/'hardware/cc2538_q22/actor.h',r/'hardware/cc2538_q22/q22_weights.h',a.contiki/'arch/platform/cooja/dev/cooja-radio.c']
 protocol=dict(scope='Separate four-node authenticated Cooja policy transfer; no physical validation',seeds=list(range(a.seed_start,a.seed_start+a.seeds)),arms=ARMS,attacks=[0,1],timings=[0,1],packets=60,interval_s=.3,positions=[[0,0],[45,15],[45,-15],[90,0]],blackhole_node=1,blackhole_pid_start=20,rx_probability=1.0,transmit_range_m=50,interference_range_m=100,feedback_expiry_ms=150,pending_retention_ms=2000,keys='public test fixtures',own_energy_queue='nominal 1 and 0',compute_delay_assumptions_ms={'outbound_data':14,'outbound_other':1,'received_public_receipt':81,'sink_received_data':31,'other_received':1},compute_delay_scope='Per-packet scheduling delays, not serial CPU service or measured cycle/power model',feature_mapping='authenticated local cache with weighted FeedbackLedger alpha/beta; frozen checkpoint, no retraining',statistical_plan={'unit':'independent simulation seed','primary':'sink delivery fraction','secondary':['critical sink deadline failures','sum of modeled transmit-state seconds'],'contrasts':'each of active, naive, frozen, censored_proof minus censored within each attack/timing stratum','families':'16 Holm-adjusted paired contrasts per endpoint; separate families clearly labeled','ci':'paired seed bootstrap, 20000 draws, fixed RNG 64001','test':'two-sided paired sign-flip randomization, 100000 draws, fixed RNG 64002; zero differences p=1'},sources_sha256={str(x.relative_to(r)) if x.is_relative_to(r) else str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in sources},checkpoint_sha256=hashlib.sha256((r/'outputs/jicce_validation/checkpoints/attention_41001.pt').read_bytes()).hexdigest(),contiki_commit=subprocess.check_output(['git','-C',str(a.contiki),'rev-parse','HEAD'],text=True).strip(),cooja_commit=subprocess.check_output(['git','-C',str(a.cooja),'rev-parse','HEAD'],text=True).strip())
